import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_in_denominator():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts_not_groups():
    groups = {"x": [{"flagged": True}], "y": [{"flagged": False}] * 3, "z": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"z": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (2, 5), (4, 6)])
def test_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected


def test_parse_skips_comments_and_strips_fields():
    lines = ["", "  \t", "  # foo", " x , 2 , 0 ", "y, 3,  "]
    assert parse_transcript_log(lines) == [
        {"id": "x", "day": 2, "flagged": False},
        {"id": "y", "day": 3, "flagged": None},
    ]


@pytest.mark.parametrize("bad", ["x,1", "x,1,1,0", "x,two,0"])
def test_parse_errors_report_original_line_number(bad):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["# comment", "x,1,0", "  ", bad])


def test_dedupe_keeps_last_record_then_sorts():
    old, b, c, new = parse_transcript_log(["a,9,1", "b,3,1", "c,1,0", "a,3,0"])
    assert dedupe_transcripts([old, b, c, new]) == [c, new, b]


def test_daily_counts_include_gaps_and_ignore_outside_days():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,5,1"])
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts(events, 3, 2) == []


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"x": parse_transcript_log(["a,1,1", "b,4,0", "c,4,"]), "y": []}
    assert monitor_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 1}
    assert monitor_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_reports_order_ties_and_handle_empty_groups():
    groups = {"z": [{"flagged": True}], "c": [], "a": [{"flagged": False}],
              "b": [{"flagged": True}]}
    assert top_flagged_groups(groups, 5) == ["b", "z", "a"]
    assert top_flagged_groups(groups, 1) == ["b"]
    assert list(flag_rate_by_group(groups).items()) == [
        ("a", 0.0), ("b", 1.0), ("c", None), ("z", 1.0)
    ]


def test_streak_requires_consecutive_positive_days():
    assert longest_flag_streak([1, 0, 1, 2, -1, 1]) == 2
    assert longest_flag_streak([]) == 0
